function mostBombs(bombs: number[][]): number {
  const n = bombs.length;
  const adj: number[][] = Array.from({ length: n }, () => []);
  for (let a = 0; a < n; a++) {
    const [xa, ya, ra] = bombs[a];
    for (let b = 0; b < n; b++) {
      if (a === b) continue;
      const dx = xa - bombs[b][0], dy = ya - bombs[b][1];
      if (dx * dx + dy * dy <= ra * ra) adj[a].push(b);
    }
  }
  let best = 0;
  for (let s = 0; s < n; s++) {
    const seen = new Array(n).fill(false);
    seen[s] = true;
    const queue = [s];
    for (let h = 0; h < queue.length; h++)
      for (const v of adj[queue[h]]) if (!seen[v]) { seen[v] = true; queue.push(v); }
    best = Math.max(best, queue.length);
  }
  return best;
}

